"""Build a portable team handoff page from actual Unity play-mode captures."""
from pathlib import Path
from collections import Counter
import base64, json, html, math, io, os
from PIL import Image

ROOT=Path(__file__).resolve().parents[2]
CAP=Path(os.environ.get('CHAPTER1_SHARE_OUTPUT',str(ROOT/'outputs/room-replacement/captures')))
OUT=ROOT/'outputs/team-share'
OUT.mkdir(parents=True, exist_ok=True)
rooms=json.loads((ROOT/'unity/Assets/ForestCombatV2/Resources/Chapter1Rooms.json').read_text(encoding='utf-8-sig'))['rooms']
layouts=[json.loads((CAP/f'layout-{i}.json').read_text(encoding='utf-8-sig')) for i in range(3)]
names={'01_field_mouse':'들쥐','02_mole':'두더지','05_boar':'멧돼지','07_scarecrow':'허수아비','08_hay_bale':'건초더미','10_water_bucket':'물통'}
assets={}
def picture(file,title,cls='',caption=''):
    path=CAP/(file+'.png')
    blueprint_sources={'blueprints-three':'starting-room-three-offers','blueprints-one':'after-first-choice','blueprints-two':'after-second-choice'}
    legacy_blueprint=file in blueprint_sources and not path.exists()
    if legacy_blueprint:
        path=ROOT/'outputs/starting-blueprints'/(blueprint_sources[file]+'.png')
    if not path.exists(): raise FileNotFoundError(path)
    if file not in assets:
        # Lossless WebP keeps the original play-mode pixels with a smaller payload.
        im=Image.open(path).convert('RGB')
        if legacy_blueprint: im=im.crop((440,160,1200,470))
        stream=io.BytesIO();im.save(stream,format='WEBP',lossless=True,method=6)
        assets[file]='data:image/webp;base64,'+base64.b64encode(stream.getvalue()).decode()
    return f'<figure class="{cls}"><button class="shot" data-image="{file}" data-title="{html.escape(title)}" aria-label="{html.escape(title)} 이미지 확대"><img src="{assets[file]}" alt="{html.escape(title)}" loading="lazy" decoding="async"><span class="enlarge">확대 보기 ↗</span></button>'+ (f'<figcaption>{caption}</figcaption>' if caption else '')+'</figure>'

cards=[]
for i,r in enumerate(rooms):
    counts=Counter(m['species'] for m in r['monsters'])
    enemies=' · '.join(f'{names.get(k,k)} {v}' for k,v in counts.items())
    terrain=r['terrain']; wood=sum(t['kind']=='wood' for t in terrain)
    cards.append(f'<article class="room"><div class="cardhead"><span class="mono">ROOM {i+1:02}</span><h3>{r["name"]}</h3><span class="pill">{len(r["monsters"])}마리</span></div>'+(picture('room-09-right',r['name']+' · 오른쪽 출입구')+picture('room-09-left',r['name']+' · 왼쪽 출입구') if i==9 else picture(f'room-{i:02}',r['name']))+f'<div class="cardfoot"><span>{r["width"]} × {r["height"]}칸 · '+('연속된 언덕' if i<6 else ['상승 계단','하강 계단','넓은 분지','ㄷ자 · 좌우 2버전','ㄹ자 · 하강 회랑','三자 · 상승 누각'][i-6])+(f' · 나무 발판 {wood}개' if wood else '')+f'</span><details><summary>몬스터 구성 보기</summary><p>{enemies}</p></details></div></article>')
connectors=[('straight','직선 길목','같은 높이의 방을 연결합니다. 최하단은 고체 지면으로 구성합니다.'),('split_up','위쪽 분기','주 경로에서 위쪽 선택 갈래로 올라갑니다.'),('split_down','아래쪽 분기','주 경로에서 아래쪽 선택 갈래로 내려갑니다.'),('merge_from_up','위쪽에서 합류','상단 선택 갈래에서 주 경로로 내려와 합류합니다.'),('merge_from_down','아래쪽에서 합류','하단 선택 갈래에서 주 경로로 올라와 합류합니다.')]
connector_html=''.join(f'<article class="connector {"wide" if k=="straight" else ""}"><div class="cardhead"><span class="mono">LINK {i+1:02}</span><h3>{title}</h3></div>'+picture('connector-'+k,title)+f'<p class="connector-note">{desc}</p></article>' for i,(k,title,desc) in enumerate(connectors))
blueprints=''.join('<article><span class="step">'+step+'</span>'+picture(file,title,caption=caption)+'</article>' for step,file,title,caption in [
    ('01 · 선택 전','blueprints-three','시작방의 도면 3개','검 · 기본 둔기 · 기본 총 도면을 제시합니다.'),
    ('02 · 첫 도면 획득','blueprints-one','검 도면을 선택한 직후','가까이 가서 E. 선택한 무기가 슬롯 1에 즉시 장착됩니다.'),
    ('03 · 두 번째 획득','blueprints-two','두 번째 도면 선택 후 남은 도면 제거','두 번째 무기는 슬롯 2에 장착되고 남은 도면은 사라집니다.')])
map_panels=[]
for i,d in enumerate(layouts):
    shop=next(r for r in d['rooms'] if r['kind']=='shop'); maintenance=next(r for r in d['rooms'] if r['kind']=='maintenance')
    labels=''.join(f'<span class="map-pin {r["kind"]}" style="left:{(r["x"]+r["w"]/2+10)/(d["cols"]+20)*100:.3f}%;top:{(r["y"]+5+(0.3*(d["cols"]+20)-d["rows"])/2)/(0.3*(d["cols"]+20))*100:.3f}%">{("상점" if r["kind"]=="shop" else "정비소" if r["kind"]=="maintenance" else "시작" if r["kind"]=="start" else "보스" if r["kind"]=="boss" else "엘리트")}</span>' for r in d['rooms'] if r['kind']!='combat')
    desc=f'상점 {"상단" if shop["y"]<d["rooms"][0]["y"] else "하단"} 갈래 · 정비소 {"상단" if maintenance["y"]<d["rooms"][0]["y"] else "하단"} 갈래'
    map_panels.append(f'<div class="map-panel" id="map-{i}" {"hidden" if i else ""}><div class="map-image">'+picture(f'layout-{i}',f'시드 {d["generationSeed"]}의 전체 스테이지')+labels+f'</div><p class="map-caption"><strong>SEED {d["generationSeed"]}</strong><span>{desc}</span><span>전투방 10개 · 전체 15개 방</span></p></div>')

page='''<!doctype html>
<html lang="ko"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="color-scheme" content="dark light"><title>Deviant · 1챕터 플레이 테스트 공유</title>
<style>
:root{--bg:#121816;--surface:#1b2420;--line:#36423a;--text:#f1f0e4;--muted:#b7c1b6;--accent:#d7e7a2;--warm:#eac191;--pad:clamp(20px,4vw,64px)}*{box-sizing:border-box}html{scroll-behavior:smooth;scroll-padding-top:88px}body{margin:0;background:var(--bg);color:var(--text);font:16px/1.7 'Malgun Gothic','Apple SD Gothic Neo',sans-serif}button,a,summary{touch-action:manipulation}button{font:inherit}a{color:inherit}button:focus-visible,a:focus-visible,summary:focus-visible{outline:3px solid var(--accent);outline-offset:4px}header{padding:34px var(--pad) 44px;max-width:1560px;margin:auto}.eyebrow,.mono{font-family:Consolas,monospace;font-size:12px;letter-spacing:.1em;color:var(--accent)}.topline{display:flex;justify-content:space-between;align-items:center;border-bottom:1px solid var(--line);padding-bottom:18px;gap:20px}.topline span:last-child{font-size:12px;color:var(--muted)}h1{font-size:clamp(34px,5vw,68px);line-height:1.25;letter-spacing:-.06em;margin:38px 0 18px;font-weight:700}h1 small{font-size:.39em;letter-spacing:0;display:block;color:var(--accent);margin-top:13px;font-weight:400}.intro{max-width:750px;color:var(--muted);font-size:17px;margin:0}.facts{display:flex;flex-wrap:wrap;gap:12px 30px;margin-top:28px}.facts span{font-size:14px;color:var(--muted)}.facts b{color:var(--text);font-size:23px;margin-right:5px}nav{position:sticky;top:0;z-index:10;background:var(--bg);border-block:1px solid var(--line);padding:0 var(--pad);display:flex;gap:24px;overflow-x:auto;white-space:nowrap}nav a{display:block;padding:17px 0;text-decoration:none;font-size:13px;color:var(--muted);border-bottom:2px solid transparent}nav a:hover,nav a.current{color:var(--accent);border-bottom-color:var(--accent)}main{max-width:1560px;margin:auto;padding:0 var(--pad)}section{padding:62px 0;border-bottom:1px solid var(--line)}.sectionhead{display:grid;grid-template-columns:64px 1fr;gap:12px;margin-bottom:28px}.number{font:40px/1.2 Georgia,serif;color:var(--accent)}h2{font-size:clamp(24px,3vw,36px);line-height:1.35;letter-spacing:-.04em;margin:0 0 12px}.sectionhead p{max-width:900px;color:var(--muted);margin:0}.pill{font-size:11px;border:1px solid #59694d;padding:2px 8px;color:var(--accent);white-space:nowrap}.gallery,.facility-grid,.combat-grid{display:grid;grid-template-columns:1fr 1fr;gap:28px 24px}.blueprints{display:grid;grid-template-columns:repeat(3,1fr);gap:18px}.step{font-size:12px;display:block;color:var(--accent);padding-bottom:9px}.room,.connector,.facility{border:1px solid var(--line);background:var(--surface)}.cardhead{display:flex;align-items:center;gap:14px;padding:14px 18px}.cardhead h3{font-size:18px;line-height:1.4;margin:0;flex:1}.cardhead .mono{font-size:10px;white-space:nowrap}.cardfoot{padding:12px 18px;color:var(--muted);font-size:12px}.cardfoot details{margin-top:9px}summary{cursor:pointer;color:var(--accent)}details p{margin-bottom:4px}figure{margin:0}.shot{position:relative;display:block;padding:0;border:0;width:100%;background:#241f1b;cursor:zoom-in;color:white}.shot img{display:block;width:100%;height:auto;image-rendering:auto}.enlarge{position:absolute;right:10px;bottom:10px;font-size:10px;background:#101b17e8;padding:3px 8px;border:1px solid #536048;opacity:0}.shot:hover .enlarge,.shot:focus-visible .enlarge{opacity:1}figcaption{font-size:13px;color:var(--muted);padding:10px 0}.note{margin-top:24px;border-left:3px solid var(--accent);padding:12px 18px;color:var(--muted);background:var(--surface);font-size:14px}.note strong{color:var(--text)}.facility p{padding:0 18px;margin:12px 0 18px;font-size:14px;color:var(--muted)}.connector.wide{grid-column:1/-1}.connector.wide figure img{max-height:370px;object-fit:contain}.connector:not(.wide) figure{background:#241f1b}.connector:not(.wide) figure img{max-height:650px;object-fit:contain}.connector-note{color:var(--muted);font-size:14px;margin:14px 18px 20px}.map-switch{display:flex;gap:10px;margin-bottom:14px;flex-wrap:wrap}.map-switch button{border:1px solid var(--line);background:var(--surface);color:var(--muted);padding:8px 15px;cursor:pointer;font-size:13px}.map-switch button[aria-selected=true]{background:var(--accent);color:#1b281a;border-color:var(--accent)}.map-image{position:relative;border:1px solid var(--line)}.map-pin{position:absolute;transform:translate(-50%,-50%);font-size:clamp(7px,1vw,12px);background:#15221ae8;line-height:1.4;color:var(--text);padding:2px 5px;pointer-events:none}.map-pin.shop{color:#ecc995}.map-pin.maintenance{color:#b8dfb8}.map-pin.boss{color:#eea991}.map-caption{display:flex;flex-wrap:wrap;gap:8px 22px;font-size:12px;color:var(--muted)}.map-caption strong{color:var(--accent);font-family:Consolas,monospace}.count{font:clamp(36px,6vw,80px)/1.3 Consolas,monospace;letter-spacing:-.06em;color:var(--accent);margin:0}.count-label{color:var(--muted);margin:0 0 24px}.formula{display:flex;gap:14px;align-items:center;flex-wrap:wrap;font-size:15px;padding:20px 0}.formula b{font-family:Consolas,monospace;font-size:24px}.formula span{color:var(--muted)}.formula-details{border-top:1px solid var(--line);padding:16px 0;color:var(--muted);font-size:14px}.timing{display:flex;width:100%;min-height:55px;margin:22px 0 10px;text-align:center;font-size:13px;color:#172019}.timing span{display:flex;justify-content:center;align-items:center;flex-direction:column;line-height:1.5;min-width:75px}.windup{background:#d5bd8d;flex:35}.active{background:#e39470;flex:12.23}.recovery{background:#a7bea0;flex:40}.timing small{font-family:Consolas,monospace}.combat-grid h3{font-size:22px;margin:0 0 12px}.combat-grid p{color:var(--muted);font-size:14px;margin:14px 0}.metric{font:34px/1.3 Consolas,monospace;color:var(--accent);margin-bottom:15px}.metric small{font:14px 'Malgun Gothic',sans-serif;color:var(--muted)}.combat-grid figure+figure{margin-top:16px}.combat-grid figcaption{font-size:12px}.footer{max-width:1560px;margin:auto;padding:32px var(--pad) 60px;color:var(--muted);font-size:12px}.footer p{margin:5px 0}.footer button{background:transparent;border:1px solid var(--line);color:var(--text);padding:8px 12px;margin-top:12px;cursor:pointer;font-size:12px}dialog{padding:0;border:1px solid var(--line);background:var(--bg);color:var(--text);max-width:96vw;width:1400px;max-height:94vh}dialog::backdrop{background:#050b09e8}.dialogbar{padding:12px 18px;display:flex;align-items:center;gap:12px;position:sticky;top:0;background:var(--bg);z-index:1;font-size:13px}.dialogbar strong{flex:1}.dialogbar button{background:var(--surface);border:1px solid var(--line);color:var(--text);padding:6px 10px;cursor:pointer}.viewer{overflow:auto;max-height:80vh;text-align:center;background:#241f1b}.viewer img{max-width:100%;max-height:78vh;object-fit:contain;vertical-align:middle}.viewer.actual img{max-width:none;max-height:none;image-rendering:pixelated}body:has(dialog[open]){overflow:hidden}[hidden]{display:none!important}
@media(min-width:1440px){.gallery{gap:34px}.sectionhead{grid-template-columns:80px 1fr}}@media(max-width:1024px){.blueprints{grid-template-columns:1fr}.blueprints article{display:grid;grid-template-columns:150px 1fr;gap:10px}.cardhead{flex-wrap:wrap;gap:6px 12px}.cardhead .mono{width:100%}.cardhead h3{font-size:16px}.sectionhead{grid-template-columns:50px 1fr}}@media(max-width:768px){.gallery,.facility-grid,.combat-grid{grid-template-columns:1fr}.blueprints article{display:block}.connector.wide{grid-column:auto}.number{font-size:30px}section{padding:38px 0}nav{gap:20px}.cardhead .mono{width:auto}.map-pin{padding:1px 2px;font-size:7px}.map-caption{display:block}.map-caption span{display:block}.enlarge{opacity:1}.topline{align-items:flex-start}.topline span:last-child{max-width:160px;text-align:right}}@media(max-width:375px){:root{--pad:14px}h1{font-size:32px}.sectionhead{grid-template-columns:36px 1fr}.facts{gap:12px}}@media(prefers-color-scheme:light){:root{--bg:#f4f3e9;--surface:#eaece0;--line:#ccd0bf;--text:#233025;--muted:#596554;--accent:#49632e}.pill{border-color:#9aaa82}nav{background:#f4f3e9}.shot{color:white}.map-pin{color:#eeeedd}.map-pin.shop{color:#ecc995}.map-pin.maintenance{color:#b8dfb8}.map-pin.boss{color:#eea991}.viewer{background:#241f1b}.dialogbar{background:var(--bg)}}@media(prefers-reduced-motion:reduce){html{scroll-behavior:auto}*{animation:none!important;transition:none!important}}@media print{nav,.enlarge,.footer button{display:none}.gallery{grid-template-columns:1fr 1fr}section{break-before:page}.room,.connector,figure{break-inside:avoid}body{background:#fff;color:#111}img{max-height:300px;object-fit:contain}.blueprints{grid-template-columns:1fr 1fr 1fr}header{padding-top:10px}.map-panel[hidden]{display:block!important}.note{color:#333}dialog{display:none}}
</style></head><body>
<header><div class="topline"><span class="eyebrow">Deviant / CHAPTER 01</span><span>팀 공유용 · 2026.10.26<br>현재 로컬 테스트 환경 기준</span></div><h1>방을 만들고,<br>연결해서 매번 다른 런으로.<small>1챕터 플레이 테스트 구현 공유</small></h1><p class="intro" data-pretext contenteditable="true">시작 무기 선택부터 방·길목 설계, 랜덤 배치, 전투 수치 조정까지. 현재 Unity에서 플레이할 수 있는 내용을 실제 렌더링 이미지로 정리했습니다.</p><div class="facts"><span><b>3 → 2</b>시작 도면 선택</span><span><b>12종</b>전투방 후보</span><span><b>5종</b>연결 길목</span><span><b>10개</b>런당 전투방</span></div></header>
<nav aria-label="공유 항목"><a href="#blueprints">01 도면 선택</a><a href="#rooms">02 방 디자인</a><a href="#facilities">03 상점·정비소</a><a href="#connectors">04 길목 디자인</a><a href="#layouts">05 맵 배치 수</a><a href="#combat">06 전투 조정</a></nav><main>
<section id="blueprints"><div class="sectionhead"><span class="number">01</span><div><h2>런 시작 시, 도면 3개 중 2개를 선택</h2><p>검·기본 둔기·기본 총 중 원하는 도면에 가까이 가서 <strong>E</strong>로 획득합니다. 선택 순서대로 무기 슬롯 1·2에 즉시 장착되며, 두 번째 선택이 끝나면 남은 도면은 사라집니다.</p></div></div><div class="blueprints">@@BLUEPRINTS@@</div><div class="note">새 배치·씬 재시작에서는 다시 선택합니다. <strong>R 전투 리셋은 도면 선택과 현재 장비를 유지</strong>합니다. 아직 선택하지 않은 무기 슬롯은 사용할 수 없습니다.</div></section>
<section id="rooms"><div class="sectionhead"><span class="number">02</span><div><h2>전투방 12종을 먼저 설계했습니다</h2><p>각 방 내부의 형태를 미리 만들고, 한 런에서 <strong>10종을 중복 없이 선택</strong>합니다. 언덕·상승·하강·분지·다층 구조에 방마다 몬스터 10마리를 배치했습니다. 아래 이미지는 현재 런에 생성된 방을 전체가 보이도록 줌아웃한 Unity 화면입니다.</p></div></div><p class="note">1~6번은 기존 언덕을 유지합니다. 7~12번은 상승·하강·분지·ㄷ·ㄹ·三 구조입니다. ㄷ자 좌우 버전은 한 종류로 계산하며, 아래 두 이미지를 함께 확인할 수 있습니다.</p><div class="gallery">@@ROOMS@@</div><div class="note">긴 교전 면과 높이 전환을 섞고, 순방향으로 이동하며 적을 만나도록 구성했습니다. 방 바깥은 충돌하는 흙 지형으로 구분하며, <strong>몬스터 배치는 HTML 방 편집기에서 계속 수정할 수 있습니다.</strong> 감지 전에는 정해진 구간에서 이동·대기를 반복합니다.</div></section>
<section id="facilities"><div class="sectionhead"><span class="number">03</span><div><h2>상점·정비소는 탐색해서 발견하는 선택 방</h2><p>주 경로를 따라가다 갈림길을 탐색하면 발견합니다. 시드에 따라 갈래의 위·아래 방향과 시설 후보가 바뀌며, 보스방은 항상 주 경로 마지막입니다. 모든 방은 로딩 전환 없이 길목으로 이어집니다.</p></div></div><div class="facility-grid"><article class="facility"><div class="cardhead"><span class="mono">OPTIONAL / SHOP</span><h3>상점</h3></div>@@SHOP@@<p>첫 번째 선택 갈래에 배치됩니다. 일반 몬스터가 없는 시설 공간입니다.</p></article><article class="facility"><div class="cardhead"><span class="mono">OPTIONAL / MAINTENANCE</span><h3>정비소</h3></div>@@MAINTENANCE@@<p>진행 중간의 두 번째 선택 갈래에 배치됩니다. 상점 갈래와 반대쪽 높이에 생성됩니다.</p></article></div><div class="note"><strong>현재 구현은 시설 위치·공간 배치까지입니다.</strong> 상점 구매와 정비소 강화 서비스 전체가 완성됐다는 의미는 아닙니다. 시설 위치는 아무 곳이나 뽑는 방식이 아니라, 정해진 진행 구간 안에서 배치됩니다.</div></section>
<section id="connectors"><div class="sectionhead"><span class="number">04</span><div><h2>방 사이를 잇는 길목 5종</h2><p>24칸 폭의 길목으로 수평 연결과 상하 갈래를 구성했습니다. 상하 방의 기준 높이 차는 48칸이며, 24칸 계단 두 구간을 이어 사용합니다. 계단 높이 차는 최대 3칸입니다. 방마다 다른 출입구 높이·방향은 별도 연결부로 잇습니다. 아래 이미지는 연결된 방까지 일부 포함한 실제 Unity 통로입니다.</p></div></div><div class="gallery">@@CONNECTORS@@</div><div class="note">최하단은 고체 지면, 그 위 분기·합류 계단은 <strong>하향 통과 가능한 나무 발판</strong>입니다. 방 출입구에는 통과 공간을 남기고, 연결되지 않은 위아래 방 사이와 맵 외곽은 흙으로 막았습니다. 길목 아래에 별도 안전 바닥을 겹쳐 놓지 않습니다.</div></section>
<section id="layouts"><div class="sectionhead"><span class="number">05</span><div><h2>배치는 얼마나 달라질 수 있나요?</h2><p>전투방의 선택·순서와 갈래 방향을 조합합니다. 아래는 실제로 생성해 촬영한 서로 다른 3개 시드의 전체 스테이지입니다. 전체 구조를 보여주기 위해 검토용으로 크게 줌아웃했으며, 시설명 표시는 설명용으로 덧붙였습니다.</p></div></div><div class="map-switch" role="tablist" aria-label="배치 예시"><button id="tab-0" role="tab" aria-selected="true" aria-controls="map-0" data-map="0">배치 예시 A</button><button id="tab-1" role="tab" aria-selected="false" aria-controls="map-1" data-map="1" tabindex="-1">배치 예시 B</button><button id="tab-2" role="tab" aria-selected="false" aria-controls="map-2" data-map="2" tabindex="-1">배치 예시 C</button></div>@@MAPS@@<div class="formula"><span>전투방 선택·순서</span><b>11P10 + (12P10 − 11P10) × 2</b><span>× 갈래 방향</span><b>2</b></div><p class="count">878,169,600</p><p class="count-label">지형 배치 기준, 설계상 최대 <strong>8억 7,816만 9,600가지</strong></p><details class="formula-details"><summary>계산 기준과 실제 생성 범위</summary><p>ㄷ자 미포함 11P10 = 39,916,800가지, ㄷ자 포함 (12P10−11P10)×좌우 2종 = 399,168,000가지입니다. 합계 439,084,800가지에 위·아래 갈래 구성 2종을 곱했습니다. 방마다 독립적으로 위·아래를 뽑는 방식은 아닙니다.</p><p>상점 원본 후보 2개와 정비소 원본 후보 3개까지 구분하면 878,169,600 × 2 × 3 = <strong>5,269,017,600가지</strong>의 설정 조합입니다. 다만 현재 시설 후보의 내부 지형은 같으므로 이 값을 서로 다른 지형 이미지 수로 세지 않았습니다.</p><p>위 수치는 <strong>설계 조합의 상한</strong>입니다. 실제 생성은 0~2,147,483,647 시드를 사용하며, 모든 시드를 중복 제거해 센 실제 도달 배치 수와 같다고 단정할 수 없습니다. 몬스터의 배회와 도면 선택 조합은 맵 배치 수에서 제외했습니다.</p></details><div class="note">한 런은 시작방 1 + 주 경로 전투방 7 + 선택 갈래 전투방 3 + 상점·정비소·엘리트 각 1 + 보스방 1 = <strong>총 15개 방</strong>입니다. 적 전멸을 요구하지 않아 전투를 피해갈 수 있으며, 플레이 지도는 탐색한 방과 인접 길목만 공개합니다.</div></section>
<section id="combat"><div class="sectionhead"><span class="number">06</span><div><h2>전투 수치는 플레이하면서 조정 중입니다</h2><p>이동과 공격을 직접 플레이하며 답답한 구간을 수정하고 있습니다. 아래 수치는 현재 로컬 테스트에 적용한 값이며, 최종 밸런스 확정값은 아닙니다.</p></div></div><div class="combat-grid"><article><h3>폭탄 · 날아가는 속도를 1.5배로</h3><div class="metric">10 → 15 <small>유닛/초 · 발사 초기 속력</small></div>@@BOMB_BASIC@@@@BOMB_SPECIAL@@<p>기본공격과 기본 특수공격에 적용했습니다. 기본 특수공격은 같은 탄도를 사용하는 폭탄 3개를 순서대로 발사합니다. 중력이 적용되는 곡사체이므로 비행 내내 일정한 속력이라는 뜻은 아닙니다.</p></article><article><h3>기본 둔기 · 1타 선딜과 후딜 조정</h3><div class="metric">0.35 / 0.40 <small>초 · 선딜 / 판정 종료 후 후딜</small></div>@@HAMMER@@<div class="timing" role="img" aria-label="기본 둔기 1타: 선딜 0.35초, 판정 지속 약 0.122초, 후딜 0.4초"><span class="windup">선딜<small>0.350 s</small></span><span class="active">판정<small>0.122 s</small></span><span class="recovery">후딜<small>0.400 s</small></span></div><p>현재 시험 공속을 반영한 실제 시간입니다. 1타 전체는 <strong>약 0.872초</strong>, 2타까지 연속 사용하면 <strong>약 1.953초</strong>입니다. 2타 수치는 이번 조정에서 유지했습니다.</p></article></div><div class="note">이번 자료의 공격 이미지는 해당 무기를 장착하고 기본공격·특수공격을 실행한 Unity 화면입니다. 속도와 시간은 화면의 인상으로 추정하지 않고 <strong>현재 데이터와 실행 검증값</strong>으로 표기했습니다.</div></section>
</main><footer class="footer"><p>Unity 6000.6.5f1 · 현재 로컬 작업본 · 2026.10.26</p><p>모든 이미지는 실제 Play 모드의 월드·캐릭터·몬스터·공격을 Unity 카메라로 렌더링했습니다. 방과 길목의 전체 형태를 보여주도록 카메라 배율을 조정했으며, HUD는 포함하지 않았습니다.</p><p>이미지를 파일 안에 포함한 단일 HTML입니다. 이 파일 하나를 팀원에게 전달하면 됩니다. 현재 로컬 변경이 모두 main에 반영되었다는 의미는 아닙니다.</p><button onclick="window.print()">인쇄 / PDF 저장</button></footer>
<dialog id="lightbox" aria-labelledby="image-title"><div class="dialogbar"><strong id="image-title"></strong><button id="pixel-size" type="button" aria-pressed="false">원본 크기</button><button id="close-image" type="button" autofocus>닫기 · Esc</button></div><div class="viewer"><img id="full-image" alt=""></div></dialog>
<script>
const dialog=document.getElementById('lightbox'),viewer=dialog.querySelector('.viewer'),full=document.getElementById('full-image'),pixel=document.getElementById('pixel-size');
document.querySelectorAll('.shot').forEach(b=>b.addEventListener('click',()=>{full.src=b.querySelector('img').src;full.alt=b.dataset.title;document.getElementById('image-title').textContent=b.dataset.title;viewer.classList.remove('actual');pixel.setAttribute('aria-pressed','false');pixel.textContent='원본 크기';dialog.showModal();}));
document.getElementById('close-image').onclick=()=>dialog.close();dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close();});pixel.onclick=()=>{const actual=viewer.classList.toggle('actual');pixel.textContent=actual?'화면에 맞춤':'원본 크기';pixel.setAttribute('aria-pressed',actual);};
function selectMap(i){document.querySelectorAll('[data-map]').forEach(b=>{const active=b.dataset.map===String(i);b.setAttribute('aria-selected',active);b.tabIndex=active?0:-1;document.getElementById('map-'+b.dataset.map).hidden=!active;});}
document.querySelectorAll('[data-map]').forEach(b=>{b.onclick=()=>selectMap(b.dataset.map);b.onkeydown=e=>{if(!['ArrowLeft','ArrowRight','Home','End'].includes(e.key))return;e.preventDefault();let n=Number(b.dataset.map);n=e.key==='Home'?0:e.key==='End'?2:(n+(e.key==='ArrowRight'?1:2))%3;selectMap(n);document.querySelector('[data-map="'+n+'"]').focus();};});
document.querySelectorAll('.map-panel').forEach((p,i)=>{p.setAttribute('role','tabpanel');p.setAttribute('aria-labelledby','tab-'+i);});
const links=[...document.querySelectorAll('nav a')];new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting)links.forEach(a=>a.classList.toggle('current',a.hash==='#'+e.target.id));},{rootMargin:'-90px 0px -60% 0px'}).observe(document.getElementById('blueprints'));
const observer=new IntersectionObserver(entries=>{for(const e of entries)if(e.isIntersecting)links.forEach(a=>a.classList.toggle('current',a.hash==='#'+e.target.id));},{rootMargin:'-90px 0px -60% 0px'});document.querySelectorAll('main section').forEach(s=>observer.observe(s));
</script>
<!-- FALLBACK: vendor/pretext.js missing, using CDN. Page content and controls work offline. -->
<script type="module">
try{const {prepare,layout}=await import('https://esm.sh/@chenglou/pretext');await document.fonts.ready;const elements=[...document.querySelectorAll('[data-pretext]')],handles=new Map();function update(el){handles.set(el,prepare(el.textContent,getComputedStyle(el).font));const line=parseFloat(getComputedStyle(el).lineHeight);el.style.minHeight=layout(handles.get(el),el.clientWidth,line).height+'px';}for(const el of elements){update(el);new ResizeObserver(()=>update(el)).observe(el);new MutationObserver(()=>update(el)).observe(el,{childList:true,subtree:true,characterData:true});}}catch(e){/* Native text flow remains available with no network. */}
</script></body></html>'''
replacements={
    '@@BLUEPRINTS@@':blueprints,'@@ROOMS@@':''.join(cards),'@@CONNECTORS@@':connector_html,'@@MAPS@@':''.join(map_panels),
    '@@SHOP@@':picture('shop-0','상점 선택 방 전체 모습'), '@@MAINTENANCE@@':picture('maintenance-0','정비소 선택 방 전체 모습'),
    '@@BOMB_BASIC@@':picture('bomb-basic','폭탄 기본공격의 비행 중 투사체',caption='기본공격 · 폭탄이 날아가는 순간'),
    '@@BOMB_SPECIAL@@':picture('bomb-special','폭탄 기본 특수공격의 비행 중 투사체',caption='기본 특수공격 · 연속 투척 중'),
    '@@HAMMER@@':picture('hammer-impact','기본 둔기 1타 판정 시점의 공격 모션',caption='기본 둔기 · 1타 타격 시점'),
}
extra='<h3 style="margin:34px 0 16px">엘리트방과 보스방도 별도 공간으로 배치</h3><div class="facility-grid"><article class="facility"><div class="cardhead"><h3>엘리트방 · 선택 갈래 끝</h3></div>'+picture('elite-0','엘리트 선택 방의 전체 형태')+'<p>후반 선택 갈래에 둔 공간입니다. 전용 엘리트 콘텐츠의 완성 여부와는 구분합니다.</p></article><article class="facility"><div class="cardhead"><h3>보스방 · 주 경로 마지막</h3></div>'+picture('boss-0','주 경로 마지막 보스방의 전체 형태')+'<p>항상 주 경로의 마지막 끝에 배치됩니다. 벽으로 닫아 다른 방에서 곧바로 떨어져 진입하지 못하게 했습니다.</p></article></div>'
page=page.replace('시설 위치는 아무 곳이나 뽑는 방식이 아니라, 정해진 진행 구간 안에서 배치됩니다.</div></section>','시설 위치는 아무 곳이나 뽑는 방식이 아니라, 정해진 진행 구간 안에서 배치됩니다.</div>'+extra+'</section>')
page=page.replace('</style>','body{word-break:keep-all} .count{overflow-wrap:anywhere}</style>')
page=page.replace('HUD는 포함하지 않았습니다.','HUD는 포함하지 않았습니다. 도면 선택 이미지는 도면이 잘 보이도록 실제 화면의 일부를 잘라 담았습니다.')
for marker,value in replacements.items(): page=page.replace(marker,value)
assert '@@' not in page
output=OUT/'chapter1-playtest-share.html';output.write_text(page,encoding='utf-8')
manifest={'date':'2026-10-26','unity':'6000.6.5f1','rooms':len(rooms),'connectors':len(connectors),'images':len(assets),'seeds':[x['generationSeed'] for x in layouts],'geometricDesignUpperBound':(math.perm(11,10)+(math.perm(12,10)-math.perm(11,10))*2)*2,'configurationDesignUpperBound':(math.perm(11,10)+(math.perm(12,10)-math.perm(11,10))*2)*12,'actualReachableUniqueLayouts':'not exhaustively measured','bytes':output.stat().st_size}
(OUT/'manifest.json').write_text(json.dumps(manifest,ensure_ascii=False,indent=2),encoding='utf-8')
print(json.dumps(manifest));print(output)
